%[text] %[text:anchor:T_A9053D4A] # Create a dataset to play with
%[text] [⇦ Return to Interpolation](file:./InterpolationSoln.m)
%[text] This live script is intended to be used with the code visible and output inline. On the **View** tab of the MATLAB Toolstrip, in the **View** section, select **Output Inline**. Alternately, select **Output Inline** using the icon ![](text:image:261f) at the top right of the Live Editor pane.
%[text] While it is certainly possible to find pre-existing datasets, it is also possible to just create your own. This script walks you through collecting two datasets by selecting points on a graph. 
%[text]{"align":"center"} ![A line trace of a left hand](text:image:0df3) ![A closed loop depicting a tree and some grass](text:image:01d5)
%[text] 1. Trace your hand
%[text] 2. Draw a closed-loop image \
[x,y] = CollectData();
%%
%[text] #### Check your dataset
%[text] Are you satisfied with the result?
% Plot a line connecting each of your points in order
plot(x,y,"*-",LineWidth=5,MarkerSize=10) %[output:6fc37409]
axis square off %[output:6fc37409]
%%
%[text] #### Save your dataset
%[text] Choose the appropriate label for your dataset and then save. If you create a later dataset that you like more, selecting the same name in the dropdown in this section will overwrite your earlier file. Then go back and [repeat this process](internal:T_A9053D4A) to save another dataset as `drawing.mat` by setting the dropdown menu appropriately in this section.
% Save the data x and y with the name selected in the dropdown
% in the Data directory
if ~isempty(matlab.project.rootProject)
    % Identify the filepath to the Data folder
    fp = fullfile(currentProject().RootFolder,"Data","testDrawing.mat");
    save(fp,"x","y")
else
    disp("Please load the project before saving this data.")
end
%%
%[text] #### Helper functions
function [x,y] = CollectData()
% Load Sample Data
load(fullfile("Data","drawing.mat"),"x","y")
end
